import{z as x,x as i,o,c as l,q as d,j as t,D as A,d as e,s as r,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"UTF-8 变长","description":"","frontmatter":{"title":"UTF-8 变长","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/utf8.md","filePath":"cs/utf8.md","lastUpdated":1791063341000}'),s={name:"cs/utf8.md"};function c(D,E,C,F,p,m){const B=i("Mermaid");return o(),l("div",null,[E[2]||(E[2]=d('<h1 id="utf-8-变长" tabindex="-1">UTF-8 变长 <a class="header-anchor" href="#utf-8-变长" aria-label="Permalink to &quot;UTF-8 变长&quot;">​</a></h1><div class="epigraph"><p>ASCII 必须仍是单字节，其余码位用前缀声明长度；续字节以 $10$ 开头，既可自同步，又让非法序列无处躲。</p><footer>—— 据 RFC 3629；The Unicode Standard 整理</footer></div><p>上一课<a href="/cs/char-unicode">字符与 Unicode</a>钉死了：抽象字符先有码位，再选字节方案；并已点名 UTF-8 把 ASCII 嵌成子集。本课不重划 <code>U+10FFFF</code>，也不从「各国代码页史」另起。缺口是：变长的<strong>比特前缀</strong>还没有写成表。没有这张表，缓冲按字节切会切断序列，超长编码会把 <code>U+0000</code> 伪装成多字节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>码位是整数；文件与套接字只看见字节。固定 32 位会把 ASCII 撑成四倍，且与 Unix 字节流习惯冲突。缺口因此不是再编号一次，而是一套前缀：首字节的前导 \\(1\\) 的个数声明总长，续字节一律 <code>10xxxxxx</code>，合法码位不得用过长形式写出。</p><p>本课只钉 UTF-8。UTF-16 代理对上一课已警告宽度不是「一个字符」；本课不把它当默认交换格式。熵与分布还没有：变长省的是常见码位的<strong>字节数</strong>，不是 Shannon 信息量。</p><h3 id="自同步不是纠错" tabindex="-1">自同步不是纠错 <a class="header-anchor" href="#自同步不是纠错" aria-label="Permalink to &quot;自同步不是纠错&quot;">​</a></h3><p>从任意字节向后扫描，遇到非 <code>10</code> 开头的即可当作候选首字节。这能发现某些截断，不能纠正翻转——那是<a href="/cs/error-correcting-intuition">纠错码</a>的几何。把 UTF-8 前缀当成汉明码，后课 CRC 会没有位置。</p><p><span class="marginnote">RFC 3629 禁止超长编码，并把合法范围限制在 Unicode 码位。Pike 与 Thompson 的原始 UTF-8 设计目标之一就是：ASCII 字节在多字节流里仍只表示 ASCII。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>码位 \\(0\\)–\\(7\\mathrm{F}\\)：一字节 <code>0xxxxxxx</code>。\\(80\\)–\\(7\\mathrm{FF}\\)：<code>110xxxxx 10xxxxxx</code>。再往上三字节、四字节，首字节分别为 <code>1110xxxx</code>、<code>11110xxx</code>。译码时必须检查：续字节形态、码位落在对应范围、不落在代理区、不超过 <code>10FFFF</code>。失败则替换或报错，不得当 Latin-1 继续吃。</p>',11)),(o(),t(n,null,{default:A(()=>[r(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CP%5B%22%E7%A0%81%E4%BD%8D%22%5D%20--%3E%20PRE%5B%22%E5%89%8D%E7%BC%80%E5%A3%B0%E6%98%8E%E9%95%BF%E5%BA%A6%22%5D%0A%20%20PRE%20--%3E%20BYTES%5B%221%20%E8%87%B3%204%20%E5%AD%97%E8%8A%82%22%5D%0A%20%20BYTES%20--%3E%20REJ%5B%22%E6%8B%92%E7%BB%9D%E8%B6%85%E9%95%BF%E4%B8%8E%E6%88%AA%E6%96%AD%22%5D%0A%20%20REJ%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%AC%A6%E5%8F%B7%E4%B8%8A%E7%9A%84%E7%86%B5%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"相等：规范化后再比码位序列。按原始字节比，同一字符的非法超长与合法短形式会变成两个串——所以必须先拒绝超长。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("有了前缀，词法扫描可以按字节走并在字符边界停下。操作系统路径仍是字节；解释成字符时声明 UTF-8，则非法序列是数据错误，不是「少见汉字」。C 的 "),a("code",null,"char"),e(" 是字节，不是码位；宽字符类型若按码位索引，与 UTF-8 存储不是同一把尺子。后课信息量把字母表当随机变量的取值，默认这张表已经能写成字节。")],-1)),E[6]||(E[6]=a("p",null,"一个 UTF-8 译码器逐字节校验的完整判定路径：",-1)),(o(),t(n,null,{default:A(()=>[r(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20B0%5B%22%E8%AF%BB%E9%A6%96%E5%AD%97%E8%8A%82%22%5D%20--%3E%20N%7B%22%E5%89%8D%E5%AF%BC%201%20%E7%9A%84%E4%B8%AA%E6%95%B0%3F%22%7D%0A%20%20N%20--%3E%7C%220xxxxxxx%20(0%20%E4%B8%AA)%22%7C%20A1%5B%22%E9%95%BF%E5%BA%A6%201%2C%20%E7%A0%81%E4%BD%8D%20%3D%20%E4%BD%8E%207%20%E4%BD%8D%22%5D%0A%20%20N%20--%3E%7C%22110xxxxx%20(2%20%E4%B8%AA)%22%7C%20R2%5B%22%E8%AF%BB%201%20%E4%B8%AA%E7%BB%AD%E5%AD%97%E8%8A%82%22%5D%0A%20%20N%20--%3E%7C%221110xxxx%20(3%20%E4%B8%AA)%22%7C%20R3%5B%22%E8%AF%BB%202%20%E4%B8%AA%E7%BB%AD%E5%AD%97%E8%8A%82%22%5D%0A%20%20N%20--%3E%7C%2211110xxx%20(4%20%E4%B8%AA)%22%7C%20R4%5B%22%E8%AF%BB%203%20%E4%B8%AA%E7%BB%AD%E5%AD%97%E8%8A%82%22%5D%0A%20%20N%20--%3E%7C%2210xxxxxx%20%E6%88%96%205%20%E4%B8%AA%E4%BB%A5%E4%B8%8A%22%7C%20BAD0%5B%22%E9%9D%9E%E6%B3%95%2C%20%E6%8A%A5%E9%94%99%22%5D%0A%20%20R2%20--%3E%20CHK%5B%22%E7%BB%AD%E5%AD%97%E8%8A%82%E5%9D%87%E4%B8%BA%2010%20%E5%BC%80%E5%A4%B4%3F%22%5D%0A%20%20R3%20--%3E%20CHK%0A%20%20R4%20--%3E%20CHK%0A%20%20CHK%20--%3E%7C%E5%90%A6%7C%20BAD1%5B%22%E6%88%AA%E6%96%AD%2F%E9%9D%9E%E6%B3%95%2C%20%E6%8A%A5%E9%94%99%22%5D%0A%20%20CHK%20--%3E%7C%E6%98%AF%7C%20RNG%5B%22%E7%A0%81%E4%BD%8D%E8%90%BD%E5%9C%A8%E8%AF%A5%E9%95%BF%E5%BA%A6%E7%9A%84%E5%90%88%E6%B3%95%E5%8C%BA%E9%97%B4%3F%3Cbr%2F%3E%E4%B8%8D%E8%B6%85%20U%2B10FFFF%2C%20%E4%B8%8D%E5%85%A5%E4%BB%A3%E7%90%86%E5%8C%BA%2C%20%E9%9D%9E%E8%B6%85%E9%95%BF%22%5D%0A%20%20RNG%20--%3E%7C%E5%90%A6%7C%20BAD2%5B%22%E6%8B%92%E7%BB%9D%20(%E5%90%AB%E8%B6%85%E9%95%BF%E4%BC%AA%E8%A3%85)%22%5D%0A%20%20RNG%20--%3E%7C%E6%98%AF%7C%20OUT%5B%22%E8%BE%93%E5%87%BA%E7%A0%81%E4%BD%8D%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=d('<p><span class="marginnote">数字实例：汉字「中」的码位是 U+4E2D（十六进制 <code>0100 1110 0010 1101</code>），落在三字节区间，装进 <code>1110xxxx 10xxxxxx 10xxxxxx</code> 得到 <code>E4 B8 AD</code>。一个纯 ASCII 文件在 UTF-8 下体积不变；若换成固定 4 字节的 UTF-32，同样内容直接膨胀到 4 倍。</span></p><p><span class="marginnote">常见误区：把「字节长度」当「字符个数」。<code>len()</code> 在 C 与多数系统调用里数的是字节，「中国」是 6 字节 2 码位；截断到 5 字节会把第二个字切成残缺序列。凡是涉及切片、求长度、按位置替换，先问清楚尺子是字节还是码位。</span></p><p><span class="marginnote">直觉类比：首字节的前导 1 像「车头报车厢数」——<code>110</code> 喊「带 1 节」，<code>11110</code> 喊「带 3 节」，续字节 <code>10</code> 开头则是每节车厢的门牌格式。在字节流任何位置掉进来，看见 <code>10</code> 开头就知道自己是车厢不是车头，向后找车头即可重新对齐——这就是「自同步」，但它只能发现损坏，修不回原文。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 NFC/NFD、字素簇、emoji 序列。也不把压缩（Huffman）提前：变长是码位到字节的语法，不是按频率编的最优码。</p><p>后课默认：文本交换用 UTF-8；长度要声明是字节还是码位；非法与超长序列不是合法数据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>UTF-8 用前缀变长，ASCII 单字节嵌入。</li><li>续字节 <code>10</code> 开头，可自同步；超长必须拒绝。</li><li>前缀能发现部分非法，不是纠错码。</li><li>出处：RFC 3629；The Unicode Standard。</li></ul>',8))])}const u=x(s,[["render",c]]);export{h as __pageData,u as default};
